 external_basis={'origin':'Hansen and Lunde, Realized Variance and Market Microstructure Noise','paper':'https://w4.stern.nyu.edu/salomon/docs/Hansen-Lunde.pdf','paper_sha256':'d745ba595974cc95c44e7c9752aa5bf0409e5c6eed274e0da1469b357ed0a2f4','support':'the volatility signature plot diagnoses sampling-frequency dependence and high-frequency microstructure contamination','selection_use':'fixed one-minute versus five-minute signature construction only; BTC direction, tails, onset, and holding application are untested; no incidence or outcomes'},
 features={'decision_grid':'every completed four-hour BTCUSDT boundary','window':'exact 1,440 coherent one-minute bars [T-24h,T)','one_minute_rv':'sum squared one-minute close-to-previous-close log returns, excluding the unavailable return before the window','five_minute_rv':'sum squared close-to-previous-close log returns of 288 exact nonoverlapping five-minute closes, excluding the unavailable return before the window','signature_ratio':'one_minute_rv/five_minute_rv, finite strict positive','realized_variation':'sqrt(five_minute_rv), finite strict positive','four_hour_return':'log(last one-minute close / first one-minute open over [T-4h,T)), finite strict nonzero','prior_ranks':'strict-prior midranks over at most 270 earlier source-valid decisions, minimum 180, current excluded','event':'signature rank>=0.80 and variation rank>=0.65 now, while immediately prior source-valid decision was not jointly eligible','recursive_reset':'all rolling windows, rank histories, and onset state reset after any invalid four-hour source block','no_imputation':True},
