 policy={'window_hours':24,'signature_rank_min':.80,'variation_rank_min':.65,'rank_history_decisions':270,'minimum_rank_history_decisions':180,'entry_delay_minutes':5,'hold_hours':24,'leverage':.5,'base_cost_per_notional_side':.0006,'stress_cost_per_notional_side':.001},
